//! Read-only shared notes keep an explicit source; selector grouping is only a
//! presentation of checked membership, never a manuscript identity rewrite.
use super::*;
use novel_storage::{UniverseCatalogueSnapshot,UniverseNotesSnapshot};
use std::collections::{BTreeMap,HashSet};

#[derive(Debug,Clone,PartialEq,Eq)]
pub(crate) struct SelectorRow{pub project_id:Option<String>,pub label:String}
fn heading(rows:&mut Vec<SelectorRow>,label:String){rows.push(SelectorRow{project_id:None,label});}
pub(crate) fn selector_rows(snapshot:&UniverseCatalogueSnapshot)->Vec<SelectorRow>{
    let projects=snapshot.projects.iter().map(|p|(p.id.as_str(),p)).collect::<HashMap<_,_>>();let members=snapshot.memberships.iter().map(|m|(m.project_id.as_str(),m)).collect::<HashMap<_,_>>();let mut displayed=HashSet::new();let mut rows=Vec::new();let mut universes=snapshot.universes.iter().collect::<Vec<_>>();universes.sort_by(|a,b|(&a.title,&a.project_id).cmp(&(&b.title,&b.project_id)));
    for universe in &universes{let Some(catalogue)=&universe.catalogue else{continue;};if universe.unavailable.is_some(){continue;}heading(&mut rows,format!("Universe · {}",universe.title));let mut groups:BTreeMap<(String,String),Vec<(String,Option<String>)>>=BTreeMap::new();
        for novel in &catalogue.novels{let group=novel.series_id.as_ref().and_then(|id|catalogue.series.iter().find(|s|&s.id==id)).map(|s|(s.title.clone(),s.id.clone())).unwrap_or_else(||("Other novels".into(),String::new()));
            if let Some(project)=projects.get(novel.project_id.as_str()){let Some(member)=members.get(novel.project_id.as_str())else{continue;};if member.status!="member"||member.universe_id.as_deref()!=Some(universe.project_id.as_str()){continue;}displayed.insert(project.id.clone());groups.entry(group).or_default().push((project.title.clone(),Some(project.id.clone())));}
            else{groups.entry(group).or_default().push(("Unavailable novel on this computer".into(),None));}
        }
        for ((title,id),mut novels) in groups{heading(&mut rows,if id.is_empty(){format!("  {title}")}else{format!("  Series · {title}")});novels.sort();for (title,project_id) in novels{rows.push(SelectorRow{project_id,label:format!("    {title}")});}}
    }
    let roots=snapshot.universes.iter().map(|u|u.project_id.as_str()).collect::<HashSet<_>>();let mut remaining=snapshot.projects.iter().filter(|p|!displayed.contains(&p.id)&&!roots.contains(p.id.as_str())).collect::<Vec<_>>();remaining.sort_by(|a,b|(&a.title,&a.id).cmp(&(&b.title,&b.id)));if !remaining.is_empty(){heading(&mut rows,"Independent novels / Membership unavailable".into());}
    for project in remaining{let unavailable=members.get(project.id.as_str()).is_none_or(|m|m.status!="unassigned");rows.push(SelectorRow{project_id:Some(project.id.clone()),label:if unavailable{format!("{} · Shared membership unavailable",project.title)}else{project.title.clone()}});}
    let available_roots=universes.iter().filter(|u|projects.contains_key(u.project_id.as_str())).collect::<Vec<_>>();if !available_roots.is_empty(){heading(&mut rows,"World notes projects".into());}for universe in available_roots{rows.push(SelectorRow{project_id:Some(universe.project_id.clone()),label:if universe.unavailable.is_some(){format!("{} · Shared catalogue unavailable",universe.title)}else{universe.title.clone()}});}rows
}
fn excerpt(text:&str)->String{let mut chars=text.chars();let mut result=chars.by_ref().take(2_000).collect::<String>();if chars.next().is_some(){result.push('…');}result}
fn records<'a>(value:&'a Value,key:&str)->&'a [Value]{value[key].as_array().map(Vec::as_slice).unwrap_or(&[])}
fn text<'a>(value:&'a Value,key:&str)->&'a str{value[key].as_str().unwrap_or("")}
pub(crate) fn notes_text(snapshot:&UniverseNotesSnapshot,query:&str)->String{
    let mut out="Shared World notes\nRead-only saved source · Shared records remain separate from this novel’s planning and canon.\n".to_owned();
    if let Some(reason)=&snapshot.unavailable{out.push_str(&format!("Unavailable: {}\n",excerpt(reason)));return out;}
    let Some(universe)=&snapshot.universe else{out.push_str("Unavailable: no checked universe source.\n");return out;};if universe.unavailable.is_some()||universe.catalogue.is_none()||universe.catalogue_revision_id.is_none(){out.push_str("Unavailable: the catalogue source is not verified.\n");return out;}
    let valid_owner=snapshot.membership.project_id==snapshot.project_id&&match snapshot.membership.status.as_str(){"member"=>snapshot.membership.universe_id.as_deref()==Some(universe.project_id.as_str())&&universe.catalogue.as_ref().unwrap().novels.iter().filter(|n|n.project_id==snapshot.project_id&&n.series_id==snapshot.membership.series_id).count()==1,"universe"=>snapshot.project_id==universe.project_id&&snapshot.membership.series_id.is_none(),_=>false};if !valid_owner{out.push_str("Unavailable: the shared source does not match the checked project membership.\n");return out;}
    out.push_str(&format!("Universe: {}\nCatalogue revision: {}\n",excerpt(&universe.title),universe.catalogue_revision_id.as_deref().unwrap()));
    if let Some(series)=snapshot.membership.series_id.as_ref().and_then(|id|universe.catalogue.as_ref()?.series.iter().find(|s|&s.id==id)){out.push_str(&format!("Series: {}\n",excerpt(&series.title)));}
    let Some(planning)=&snapshot.planning else{out.push_str("No saved shared world records yet.\n");return out;};out.push_str(&format!("World notes revision: {}\n\n",planning.revision_id));let doc=&planning.payload;let query=query.to_lowercase();let mut shown=0usize;let mut work=0usize;let mut limited=false;
    for record in records(doc,"records").iter().take(20_000){work+=1;if work>20_000{limited=true;break;}let aliases=records(record,"aliases").iter().filter_map(Value::as_str).collect::<Vec<_>>().join(" ");if !format!("{} {aliases}",text(record,"name")).to_lowercase().contains(&query){continue;}if shown>=100{limited=true;break;}shown+=1;
        out.push_str(&format!("{} · {}\n{}\n",excerpt(text(record,"name")),excerpt(text(record,"kind")),excerpt(text(record,"notes"))));
        for field in records(doc,"fields").iter().filter(|f|f["recordKind"]==record["kind"]&&f["hidden"]!=true){work+=1;if work>20_000{limited=true;break;}let Some(value)=field["id"].as_str().and_then(|id|record["values"].get(id))else{continue;};let value=if let Some(value)=value.as_str(){value.to_owned()}else if value.is_number()||value.is_boolean(){value.to_string()}else if let Some(values)=value.as_array().filter(|v|v.iter().all(Value::is_string)){values.iter().filter_map(Value::as_str).collect::<Vec<_>>().join(" · ")}else{continue;};out.push_str(&format!("{}: {}\n",excerpt(text(field,"label")),excerpt(&value)));}
        let mut facts=0;for fact in records(doc,"facts"){work+=1;if work>20_000{limited=true;break;}if fact["subjectId"]!=record["id"]{continue;}if facts>=100{limited=true;break;}facts+=1;let status=if fact["confirmed"]==true&&fact["status"]=="fact"{"Approved fact"}else{text(fact,"status")};out.push_str(&format!("{}: {} · {}\nAuthor source: {}\n",excerpt(text(fact,"property")),excerpt(text(fact,"value")),excerpt(status),excerpt(text(fact,"source"))));}out.push('\n');if work>20_000{break;}
    }
    if shown==0{out.push_str("No matching saved world records.\n");}if limited||records(doc,"records").len()>20_000{out.push_str("Shared reference limit reached; stored source data is retained.\n");}out
}
struct WorldPage{origin:Rc<Workspace>,project:String,panel:Rc<Panel>,snapshot:RefCell<Option<UniverseNotesSnapshot>>,filter:gtk::Entry,buffer:gtk::TextBuffer,status:gtk::Label,generation:Cell<u64>}
impl WorldPage{
    fn owner(&self)->Option<Rc<Workspace>>{let mut owner=None;desk::with_button_owner(self.panel.widget.upcast_ref(),||{let a=desk::effective(&self.origin);if !a.desk.is_closed()&&*a.pid.borrow()==self.project&&a.pages.page_num(&self.panel.widget).is_some(){owner=Some(a);}});owner}
    fn render(&self){if let Some(snapshot)=self.snapshot.borrow().as_ref(){self.buffer.set_text(&notes_text(snapshot,self.filter.text().as_str()));}}
    fn load(self:&Rc<Self>){let Some(owner)=self.owner()else{return;};let generation=self.generation.get()+1;self.generation.set(generation);*self.snapshot.borrow_mut()=None;self.buffer.set_text("");self.status.set_text("Loading saved shared World notes…");let page=self.clone();owner.client.rpc("universe_notes_snapshot",json!({"projectId":self.project}),move|reply|{if page.generation.get()!=generation||page.owner().is_none(){return;}match reply{Ok(value)=>match serde_json::from_value::<UniverseNotesSnapshot>(value){Ok(snapshot)if snapshot.project_id==page.project=>{page.status.set_text(if snapshot.unavailable.is_some(){"Shared World notes unavailable · Local writing remains available"}else{"Saved shared World notes · Read-only source"});*page.snapshot.borrow_mut()=Some(snapshot);page.render();},_=>page.status.set_text("Shared World notes response did not match this project.")},Err(error)=>page.status.set_text(&format!("Shared World notes unavailable. {error}"))}});}
}
impl Workspace{
    pub(super) fn universe_world_notes(self:&Rc<Self>){let owner=desk::effective(self);let project=owner.pid.borrow().clone();if project.is_empty(){owner.error("Choose a novel or universe before opening World notes.");return;}let origin=owner.clone();owner.navigate(move||{if origin.desk.is_closed()||*origin.pid.borrow()!=project{return;}let panel=origin.panel("World notes");let body=panel.content_area();let filter=gtk::Entry::new();filter.set_placeholder_text(Some("Find a shared person or place"));filter.set_max_length(1000);filter.set_tooltip_text(Some("Filter shared World notes"));body.pack_start(&filter,false,false,0);let status=gtk::Label::new(None);status.set_xalign(0.);status.set_line_wrap(true);body.pack_start(&status,false,false,0);let view=gtk::TextView::new();view.set_editable(false);view.set_cursor_visible(false);view.set_wrap_mode(gtk::WrapMode::WordChar);body.pack_start(&scroll(&view),true,true,0);let page=Rc::new(WorldPage{origin:origin.clone(),project,panel:panel.clone(),snapshot:RefCell::new(None),filter:filter.clone(),buffer:view.buffer().unwrap(),status,generation:Cell::new(0)});let weak=Rc::downgrade(&page);filter.connect_changed(move|_|{if let Some(page)=weak.upgrade(){if page.owner().is_some(){page.render();}}});let p=page.clone();button(&body,"Refresh saved World notes",move||p.load());panel.show_all();page.load();});}
}
